CREATE TABLE IF NOT EXISTS outbox_delivery(event_id VARCHAR(32) PRIMARY KEY,attempts INT NOT NULL DEFAULT 0,next_attempt_at DATETIME(6) NULL,dead_at DATETIME(6) NULL,last_error VARCHAR(2000) NOT NULL DEFAULT '',FOREIGN KEY(event_id) REFERENCES outbox(id));
CREATE TABLE IF NOT EXISTS outbox_failures(id VARCHAR(32) PRIMARY KEY,event_id VARCHAR(32) NOT NULL,attempt INT NOT NULL,reason VARCHAR(2000) NOT NULL,created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(event_id) REFERENCES outbox(id));
